create or replace function public.factory_bind_github_issue(p_run_id uuid,p_issue_number integer,p_issue_url text) returns void language plpgsql security invoker set search_path='' as $$ declare v_task_id uuid;v_project_id uuid;begin if p_issue_number is null or p_issue_number<1 then raise exception 'invalid issue number';end if;select r.task_id,t.project_id into v_task_id,v_project_id from public.factory_runs r join public.factory_tasks t on t.id=r.task_id where r.id=p_run_id for update of r;if v_task_id is null then raise exception 'run not found';end if;update public.factory_runs set metadata=metadata||jsonb_build_object('github_issue',jsonb_build_object('number',p_issue_number,'url',p_issue_url)) where id=p_run_id;insert into public.factory_audit_events(project_id,task_id,run_id,actor_type,actor_ref,event_type,payload) values(v_project_id,v_task_id,p_run_id,'system','execution-worker','github.issue.bound',jsonb_build_object('number',p_issue_number,'url',p_issue_url));end;$$;
revoke all on function public.factory_bind_github_issue(uuid,integer,text) from public,anon,authenticated;
grant execute on function public.factory_bind_github_issue(uuid,integer,text) to service_role;
